\end{tikzpicture}
[/tikz]
$\begin{align*}P(2<X<4)&=F(4)-F(2)\\&=\frac34-\frac13\\&=\frac5{12}.\end{align*}$

For $-3\le x\le0$:
$\begin{align*}F(x)&=\int_{-3}^x\frac{3+t}{9}\,dt\\&=\left[\frac{(3+t)^2}{18}\right]_{-3}^x\\&=\frac{(3+x)^2}{18}.\end{align*}$
The accumulated probability is $F(0)=\frac12$.
For $0<x\le3$:
$\begin{align*}F(x)&=\frac12+\int_0^x\frac{3-t}{9}\,dt\\&=\frac12+\left[-\frac{(3-t)^2}{18}\right]_0^x\\&=1-\frac{(3-x)^2}{18}.\end{align*}$
Thus
$F(x)=\begin{cases}0,&x<-3,\\\dfrac{(3+x)^2}{18},&-3\le x\le0,\\1-\dfrac{(3-x)^2}{18},&0<x\le3,\\1,&x>3.\end{cases}$
The pieces agree at $0$, and $F(-3)=0$, $F(3)=1$.
